import type { Exercise } from "./types";
import { authoring } from "./authoring";

const { toEs, fe, wo, mc } = authoring("es");

// Condicional perfecto -> también «hubiera + participio» en la apódosis (muy común).
const HB: Record<string, string> = { "ía": "iera", "ías": "ieras", "íamos": "iéramos", "íais": "ierais", "ían": "ieran" };
const hb = (s: string) => s.replace(/\b([Hh])abr(ía|ías|íamos|íais|ían)/g, (_m, h: string, suf: string) => h + "ub" + HB[suf]);

// «Quizá / quizás / tal vez» + condicional (indicativo) o imperfecto/pluscuamperfecto (subjuntivo); «a lo mejor» solo con indicativo.
const qa = (pre: string, post: string, inds: string[], subjs: string[], start = false): string[] => {
  const out: string[] = [];
  const cap = (s: string) => (start ? s.charAt(0).toUpperCase() + s.slice(1) : s);
  for (const adv of ["quizá", "quizás", "tal vez"]) for (const v of [...inds, ...subjs]) out.push(`${pre}${cap(adv)} ${v}${post}`);
  for (const v of inds) out.push(`${pre}${cap("a lo mejor")} ${v}${post}`);
  return out;
};

// Tres fórmulas de consejo.
const iw = (t: string): string[] => ["Si yo fuera tú, " + t, "Si fuera tú, " + t, "Yo en tu lugar, " + t, "Yo que tú, " + t];
const ifw = (src: string, t: string, expl: string, extra: string[] = [], prompt?: string): Exercise => {
  const a = iw(t);
  return toEs(src, a[0], expl, [...a.slice(1), ...extra], prompt);
};

